try {
  // Gemini 的回應在 response 屬性中
  const responseText = $json.response;

  // 移除可能存在的 Markdown 格式 (```json ... ```)
  const cleanedText = responseText.replace(/```json\n|```/g, '').trim();

  // 解析 JSON 字串
  const vocabularyList = JSON.parse(cleanedText);

  // 確保回傳的是一個陣列
  if (Array.isArray(vocabularyList)) {
    return vocabularyList.map(item => ({ json: item }));
  } else {
    return [{ json: vocabularyList }];
  }
} catch (error) {
  // 如果解析失敗，回傳錯誤訊息，方便除錯
  return [{ json: { error: 'Failed to parse Gemini response', details: error.message, originalResponse: $json.response } }];
}

// 1. 從檔名提取日期
const fileName = $json.srtFile.filename;
// 新的邏輯: 尋找 YYYYMMDD 格式的日期
// 使用正規表示式尋找檔名開頭的8位數字 (例如: 20250714)
const dateMatch = fileName.match(/^(\d{8})/);
let newsDate;

if (dateMatch) {
    const dateString = dateMatch[1]; // 取得匹配到的字串，例如 "20250714"
    const year = dateString.substring(0, 4);
    const month = dateString.substring(4, 6);
    const day = dateString.substring(6, 8);
    // 將其格式化成 Notion 接受的 "YYYY-MM-DD" 格式
    newsDate = `${year}-${month}-${day}`;
} else {
    // 如果檔名開頭找不到8位數字，則使用今天的日期作為備用
    newsDate = new Date().toISOString().split('T')[0];
}

// 2. 解析 SRT 檔案內容 (最終修正版)
// 使用 n8n 的內建輔助函數，這是讀取檔案內容最可靠的方法
const fileBuffer = await this.helpers.getBinaryDataBuffer('srtFile');

// 直接將 Buffer 轉換為 utf8 字串
const srtContent = fileBuffer.toString('utf8');

const textOnly = srtContent
  .replace(/\d+\n/g, '')
  .replace(/\d{2}:\d{2}:\d{2},\d{3} --> \d{2}:\d{2}:\d{2},\d{3}\n/g, '')
  .replace(/<[^>]*>/g, '')
  .replace(/\r/g, '')
  .replace(/\n{2,}/g, ' ')
  .trim();

const sentences = textOnly.split(/[.!?]+/).filter(sentence => sentence.trim().length > 0);

// 3. 將日期和句子一起輸出
// 將解析出來的 newsDate 附加到每一個句子項目中
return sentences.map(sentence => ({ 
  json: { 
    sentence: sentence.trim(),
    newsDate: newsDate
  } 
}));

